const u = $input.first().json;
if (u.callback_query) {
  const cb = u.callback_query;
  const [action, id] = String(cb.data || '').split('|');
  return [{ json: { type: action === 'pc' ? 'clic_profil' : 'clic', action, id, query_id: cb.id,
    chat_id: String(cb.message?.chat?.id || ''), message_id: cb.message?.message_id } }];
}
const m = u.message || u.edited_message || {};
return [{ json: { type: 'message', chat_id: String(m.chat?.id || ''), texte: m.text || '' } }];

const norm = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const get = (j, key) => { const k = Object.keys(j).find(x => norm(x) === key); return k ? String(j[k] ?? '').trim() : ''; };
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const msg = $('Lire la mise à jour').first().json;
let existant = '';
const profil = {};
for (const i of $input.all()) {
  const c = get(i.json, 'cle'), v = get(i.json, 'valeur');
  if (!c) continue;
  if (c === 'chat_id') existant = v;
  else if (!c.startsWith('_') && v) profil[c] = v;
}
const texte = String(msg.texte || '').trim();
const t = norm(texte);
let commande;
if (!existant) commande = 'inscription';
else if (existant !== msg.chat_id) commande = 'refus';
else if (!texte || t.startsWith('/start') || t.startsWith('/aide') || t.startsWith('/help')) commande = 'aide';
else if (t.startsWith('/profil')) commande = 'profil';
else if (t.startsWith('/liens')) commande = 'liens';
else if (t.startsWith('/offres')) commande = 'offres';
else if (t.startsWith('/avoir')) commande = 'avoir';
else if (t.startsWith('/stats')) commande = 'stats';
else if (t.startsWith('/panne')) commande = 'panne';
else if (t.startsWith('/')) commande = 'aide';          // commande inconnue : message d'usage
else commande = 'modif';

const profil_html = Object.entries(profil)
  .filter(([k]) => k !== 'Profil mis à jour le')
  .map(([k, v]) => '<b>' + esc(k) + '</b> : ' + esc(v.length > 160 ? v.slice(0, 160) + '…' : v))
  .join('\n').slice(0, 3600);

return [{ json: { commande, chat_id: msg.chat_id, texte, profil_texte: JSON.stringify(profil), profil_html: profil_html || 'Ton profil est vide : remplis le formulaire avec /liens.' } }];

