  .filter(c => c && c.cle && !String(c.cle).startsWith('_') && c.cle !== 'chat_id')
  .map(c => ({ cle: String(c.cle).trim(), valeur: String(c.valeur ?? '').trim() }))
  .slice(0, 8);
const comprise = !!r.comprise && ch.length > 0;
const details = ch.map(c => '• <b>' + esc(c.cle) + '</b> : ' + esc(profil[c.cle] || '(vide)') + ' → ' + esc(c.valeur || '(vide)')).join('\n');
return [{ json: {
  comprise, chat_id: a.chat_id,
  en_attente: JSON.stringify({ changements: ch }),
  message: '✍️ ' + esc(r.resume || 'Voici ce que je vais changer :') + '\n\n' + details + '\n\nJe confirme ?'
} }];

