const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lettre = String($input.first().json.text || '').replace(/```/g, '').trim();
const d = $('Préparer la décision').first().json;
const p = $('Profil + offre').first().json;
const message_tg =
  '📝 <b>Ta lettre pour « ' + esc(d.titre) + ' »</b>\n' + esc(d.entreprise) + '\n\n' +
  esc(lettre).slice(0, 3400) +
  '\n\n✍️ Relis-la et ajuste-la si besoin, puis postule avec le lien de l’offre :\n🔗 ' + esc(d.url);
return [{ json: {
  lettre, lettre_html: esc(lettre).replace(/\n/g, '<br>'),
  objet: 'Candidature – ' + d.titre + ' – ' + d.entreprise,
  message_tg, cv_id: p.cv_id, cv_configure: p.cv_configure,
  chat_id: d.chat_id, id: d.id, url: d.url
} }];

const norm = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const get = (j, key) => { const k = Object.keys(j).find(x => norm(x) === key); return k ? String(j[k] ?? '').trim() : ''; };
const clic = $('Lire la mise à jour').first().json;
let attente = '';
for (const i of $input.all()) if (get(i.json, 'cle') === '_modif_en_attente') attente = get(i.json, 'valeur');
let changements = [];
try { changements = JSON.parse(attente).changements || []; } catch (e) {}

// on vide toujours la modification en attente
const lignes = [{ cle: '_modif_en_attente', valeur: '' }];
let texte;
if (clic.id === 'ok' && changements.length) {
  for (const c of changements) lignes.push({ cle: String(c.cle), valeur: String(c.valeur ?? '') });
  texte = '✅ Profil mis à jour :\n' + changements.map(c => '• ' + c.cle + ' : ' + (c.valeur || '(vide)')).join('\n') +
    '\n\nLe radar en tiendra compte dès la prochaine recherche (cette nuit à 3h).';
} else if (clic.id === 'ok') {
  texte = '⚠️ Cette modification n’est plus disponible. Réécris-moi ce que tu veux changer.';
} else {
  texte = '↩️ Modification annulée, ton profil n’a pas changé.';
}
return lignes.map(l => ({ json: { ...l, chat_id: clic.chat_id, texte } }));

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const a = $('Analyser le message').first().json;
const icone = { oui: '✅', voir: '🟠', non: '❌' };
const rows = $input.all().map(i => i.json)
  .filter(r => r && icone[r.decision] && !String(r.offre_id || '').startsWith('TEST'));
const n = d => rows.filter(r => r.decision === d).length;
let texte = '📊 <b>Bilan de tes décisions</b>\n\n' +
  '✅ Candidatures : ' + n('oui') + '\n' +
  '🟠 À voir : ' + n('voir') + '\n' +
  '❌ Refusées : ' + n('non') + '\n\n' +
  'Total : ' + rows.length + ' décision(s) enregistrée(s).';
if (rows.length) texte += '\n\n<b>Dernières :</b>\n' + rows.slice(0, 3).map(r => icone[r.decision] + ' ' + esc(r.titre) + ' — ' + esc(r.entreprise)).join('\n');
return [{ json: { chat_id: a.chat_id, texte } }];
